package com.bank.verify.service;

import com.bank.verify.model.DigitNode;
import java.util.logging.Logger;

// Checks whether a digit chain is a palindrome in O(1) extra space.
public class PalindromeCodeChecker {
    private static final Logger log = Logger.getLogger(PalindromeCodeChecker.class.getName());

    public boolean isPalindrome(DigitNode head) {
        if (head == null || head.next == null) return true;

        // 1. Find the middle with fast-slow pointers.
        DigitNode slow = head, fast = head;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
        }

        // 2. Reverse the second half starting at slow.
        DigitNode secondHead = reverse(slow);

        // 3. Compare first half and reversed second half.
        boolean palindrome = true;
        DigitNode p1 = head, p2 = secondHead;
        while (p2 != null) {
                if (p1.digit != p2.digit) { palindrome = false;
                break; }
            p1 = p1.next;
            p2 = p2.next;
        }

        // 4. Restore the list by reversing the second half again.
        reverse(secondHead);

        final boolean result = palindrome;
        if (result) log.info("Code chain is a palindrome (valid).");
        else        log.warning("Code chain is NOT a palindrome.");
        return result;
    }

    private DigitNode reverse(DigitNode node) {
        DigitNode prev = null;
        while (node != null) {
            DigitNode next = node.next;
            node.next = prev;
            prev = node;
            node = next;
        }
        return prev;
    }
}
