package com.bank.verify;

import com.bank.verify.model.DigitNode;
import com.bank.verify.service.PalindromeCodeChecker;
import java.util.logging.Logger;

public class PalindromeDemo {
    private static final Logger log = Logger.getLogger(PalindromeDemo.class.getName());

    public static void main(String[] args) {
        PalindromeCodeChecker checker = new PalindromeCodeChecker();

        DigitNode good = chain(new int[]{1, 2, 2, 1}); // palindrome
        log.info(() -> "1221 palindrome: " + checker.isPalindrome(good));

        DigitNode bad = chain(new int[]{1, 2, 3, 4});  // not a palindrome
        log.info(() -> "1234 palindrome: " + checker.isPalindrome(bad));
    }

    private static DigitNode chain(int[] digits) {
        DigitNode dummy = new DigitNode(-1);
        DigitNode tail = dummy;
        for (int d : digits) { tail.next = new DigitNode(d); tail = tail.next; }
        return dummy.next;
    }
}
